/**
 * Separate Boss quiz (Student Records): 12 questions, 1 easy / 5 medium / 6 hard (10/40/50), ordered easy to hard.
 * Every question combines at least two World 6 lessons. Types: predict_output 4, find_error 2, multi_select 2,
 * single_choice 2, code_comparison 1, fill_blank 1.
 */
export const WORLD_6_BOSS_QUIZ: QuizQuestion[] = [
  s('w6q-boss-1',L.boss,T.boss,'Growing roster: mutable List versus fixed or read-only','easy','Students enroll all term, so the roster must grow. Which declaration fits?',['val roster = mutableListOf("Ari")','val roster = listOf("Ari")','val roster = arrayOf("Ari")','val roster = setOf("Ari")'],0,'mutableListOf is the only option that can add a new student. listOf and setOf are read-only, and an Array has a fixed size.','Which factory builds a collection that can add values?'),
  p('w6q-boss-2',L.boss,T.boss,'Set membership with a Map loop','medium','What does this program print?',['fun main() {','  val passed = setOf("Ari", "Noah")','  val scores = mapOf("Ari" to 8, "Mia" to 6, "Noah" to 9)','  var sum = 0','  for ((name, score) in scores) {','    if (passed.contains(name)) sum += score','  }','  println(sum)','}'],['17','23','14','8'],0,'Only Ari and Noah are in the Set, so only their scores 8 and 9 are added: 17. Mia is skipped.','Add a score only when its name is in the Set.'),
  fb('w6q-boss-3',L.boss,T.boss,'Remove a Map entry by key','medium','Complete the call that removes Mia from the score book.',['fun main() {','  val scores = mutableMapOf("Ari" to 8, "Mia" to 6)','  scores.___("Mia")','  println(scores.containsKey("Mia"))','}'],['remove','removeAt','erase','pop'],'remove','A mutable Map removes an entry by its key with remove(key). removeAt is for List positions, and erase and pop are not Map functions. After the removal, containsKey("Mia") is false.','A Map entry is identified by its key, not by a position.'),
  p('w6q-boss-4',L.boss,T.boss,'Array update, loop total and contentToString','medium','What does this program print?',['fun main() {','  val marks = arrayOf(70, 85, 60)','  marks[2] = marks[1] + 5','  var total = 0','  for (m in marks) total += m','  println(marks.contentToString() + " " + total)','}'],['[70, 85, 90] 245','[70, 85, 60] 215','[70, 85, 90] 215','[70, 85, 90] 90'],0,'marks[2] becomes 85 + 5 = 90, so the Array is [70, 85, 90] and the loop total is 70 + 85 + 90 = 245.','Do the assignment first, then loop over the changed Array.'),
  s('w6q-boss-5',L.boss,T.boss,'Sorted copy leaves the original unchanged','medium','The List `marks` must stay in entry order, and `ranked` must hold a new sorted List. Which line does that?',['val ranked = marks.sorted()','marks.sorted()','val ranked = marks.sort()','val ranked = marks.sortedCopy()'],0,'sorted() returns a new sorted List and leaves marks alone. Calling it without storing the result throws the copy away. sort() is not available on a read-only List, and sortedCopy() does not exist.','Which call returns a new List that you can store?'),
  cc('w6q-boss-6',L.boss,T.boss,'Map entries in a loop','medium','Which program prints each student on its own line in the form `Ari: 8`?',['fun main() {','  val scores = mapOf("Ari" to 8, "Mia" to 6)','  for ((name, score) in scores) {','    println("$name: $score")','  }','}'],['fun main() {','  val scores = mapOf("Ari" to 8, "Mia" to 6)','  for (entry in scores) {','    println(entry)','  }','}'],0,'The first program splits each entry into name and score and builds the text. The second prints the whole entry, which looks like Ari=8.','What does printing one whole Map entry look like?'),
  fe('w6q-boss-7',L.boss,T.boss,'Array has a fixed size','hard','Tap the line that does not compile.',['fun main() {','  val marks = arrayOf(70, 85)','  marks[1] = 90','  println(marks.contentToString())','  marks.add(60)','  println(marks.size)','}'],4,'Replacing marks[1] is fine, but an Array has a fixed size and no add function. Use a mutable List when a new value must be appended.','Which line tries to make the Array bigger?','Array has no add function.'),
  p('w6q-boss-8',L.boss,T.boss,'remove(value) versus removeAt(index)','hard','What does this program print?',['fun main() {','  val scores = mutableListOf(10, 2, 7, 4)','  scores.remove(2)','  scores.removeAt(2)','  scores[0] = scores[1] + scores.size','  println(scores)','}'],['[9, 7]','[4, 2]','[9, 4]','[10, 7]'],0,'remove(2) deletes the value 2, giving [10, 7, 4]. removeAt(2) deletes the element at index 2 (the 4), giving [10, 7]. Then scores[0] becomes 7 + 2 = 9, so the List is [9, 7].','One call removes a value, the other removes a position. Redraw the List after each call.'),
  ms('w6q-boss-9',L.boss,T.boss,'Set, Map and read-only rules','hard','Look at this code. Select the 2 true statements.',['After `enrolled.add("Ari")`, `enrolled.size` is still 2','`grades.containsKey("Mia") && enrolled.contains("Mia")` is true','`enrolled[0]` reads "Ari" like a List would','`grades["Zed"] = 5` adds Zed to the Map'],[0,1],'Ari is already in the Set, so the size stays 2. Mia is a Map key and a Set value, so both checks are true. A Set has no index, and a read-only Map from mapOf has no way to assign a new key.','Check each statement against the factory used: mutableSetOf or mapOf.'),
  fe('w6q-boss-10',L.boss,T.boss,'A loop variable cannot be reassigned','hard','Tap the line that does not compile.',['fun main() {','  val marks = mutableListOf(60, 75)','  for (mark in marks) {','    mark = mark + 5','  }','  println(marks)','}'],3,'The loop variable mark is a val for each pass, so it cannot be reassigned, and changing it would not change the List anyway. Use an index, for example marks[0] = marks[0] + 5, to update an element.','Can the loop variable be given a new value?','A loop variable is read-only.'),
  ms('w6q-boss-11',L.boss,T.boss,'List versus Set on repeated names','hard','Given `val roster = listOf("Ari", "Mia", "Ari")`, select the 2 true statements.',['`roster.indexOf("Ari")` is 0, the first match','`roster.last()` is "Mia"','`setOf("Ari", "Mia", "Ari").size` equals `roster.size - 1`','`roster.isNotEmpty()` is false because Ari repeats'],[0,2],'indexOf returns the first match, 0. The roster has 3 entries and the Set keeps 2 unique names, so 2 equals 3 - 1. last() is the second "Ari", and a List with entries is not empty.','Count the List entries, then the unique values.'),
  p('w6q-boss-12',L.boss,T.boss,'Full record trace with a removed student','hard','What does this program print?',['fun main() {','  val roster = mutableListOf("Ari", "Mia", "Noah")','  val scores = mutableMapOf("Ari" to 4, "Mia" to 6, "Noah" to 5)','  val seen = mutableSetOf<String>()','  roster.removeAt(roster.indexOf("Mia"))','  scores.remove("Mia")','  roster.add("Ari")','  for (name in roster) {','    seen.add(name)','  }','  var total = 0','  for ((name, score) in scores) {','    if (seen.contains(name)) total += score','  }','  val position = roster.indexOf("Mia")','  println("${roster.size}/${seen.size}/$total/$position")','}'],['3/2/9/-1','3/3/9/-1','3/2/15/-1','3/2/9/null'],0,'After removing Mia the roster is Ari, Noah, and adding Ari again gives 3 entries. The Set keeps 2 unique names. The Map now holds Ari 4 and Noah 5, so the total is 9. Mia is gone, so indexOf returns -1.','Track the roster, the Set and the Map separately, and remember what indexOf returns for a missing value.'),
];

